// Code node "Classify event" (run once for all items). Webhook branch.
// Input: a PracticeQ appointment event forwarded by the "IntakeQ Appointments -> GHL"
// workflow. Output: one queue row for the "booking_summary_queue" data table.
//
// Every appointment event is queued, so later changes (another booking, a reschedule, a
// cancellation) push a waiting patient's PDF back. Only a new, open, future appointment
// (`isBooking`) makes a PDF happen at all; the sweeper drops patients with no booking row.
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();

return $input.all().flatMap(({ json }) => {
  const e = json.body && typeof json.body === 'object' ? json.body : json;
  const a = e.Appointment || {};
  const clientId = a.ClientId || e.ClientId;
  if (!clientId) return [];
  return [{
    json: {
      clientId: String(clientId),
      clientName: a.ClientName || '',
      clientEmail: a.ClientEmail || '',
      eventAt: now,
      isBooking: e.EventType === 'AppointmentCreated' && OPEN.includes(a.Status) && Number(a.StartDate) > now,
      attempts: 0,
    },
  }];
});

// Code node "Business hours?" (run once for all items). Sweeper branch.
// Lets the run continue only during business hours plus `afterCloseMinutes` after closing,
// in the practice's time zone, and never on a listed holiday. Outside that window nothing is
// processed; queued patients wait for the next opening.
const s = $('Settings').first().json;
const hours = JSON.parse(s.businessHours);
const holidays = String(s.holidays || '').split(',').map((d) => d.trim()).filter(Boolean);

const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: s.timezone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date(Date.now())).map((p) => [p.type, p.value]),
);
const day = parts.weekday.toLowerCase().slice(0, 3);
const date = `${parts.year}-${parts.month}-${parts.day}`;
const minute = Number(parts.hour) * 60 + Number(parts.minute);
const toMinute = (hhmm) => { const [h, m] = hhmm.split(':').map(Number); return h * 60 + m; };

const span = hours[day];
const open = Array.isArray(span) && !holidays.includes(date)
  && minute >= toMinute(span[0]) && minute < toMinute(span[1]) + Number(s.afterCloseMinutes || 0);
return open ? [{ json: { open: true, day, date } }] : [];

// Code node "Due patients" (run once for all items). Sweeper branch.
// Input: every row in the "booking_summary_queue" data table. Output: one item per patient
// whose last appointment event is at least `bufferMinutes` old. `upTo` is that last event
// time; rows up to it are removed from the queue, later rows stay for the next round.
// Patients whose events include no new booking come out with `discard: true` (removed from
// the queue, no PDF). At most MAX_PER_RUN PDFs per run, so a run finishes well inside 5 minutes.
const s = $('Settings').first().json;
const MAX_PER_RUN = 10;
const now = Date.now();
const bufferMs = Number(s.bufferMinutes) * 60000;

const groups = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.clientId) continue;
  (groups[String(r.clientId)] = groups[String(r.clientId)] || []).push(r);
}

const due = [];
const discard = [];
for (const [clientId, rows] of Object.entries(groups)) {
  rows.sort((a, b) => Number(a.eventAt) - Number(b.eventAt));
  const upTo = Number(rows[rows.length - 1].eventAt);
  if (upTo + bufferMs > now) continue; // still inside the buffer
  const latest = (field) => [...rows].reverse().map((r) => r[field]).find((v) => v) || '';
  const item = {
    clientId,
    name: latest('clientName'),
    email: latest('clientEmail'),
    attempts: Math.max(...rows.map((r) => Number(r.attempts) || 0)),
    upTo,
    discard: !rows.some((r) => r.isBooking === true || r.isBooking === 'true'),
  };
  (item.discard ? discard : due).push(item);
}
due.sort((a, b) => a.upTo - b.upTo);
return [...due.slice(0, MAX_PER_RUN), ...discard].map((json) => ({ json }));

// Code node "Keep due" (run once for all items). Sweeper branch.
// The queue rows are removed by now; continue with the patients who get a PDF.
return $('Due patients').all().filter((i) => !i.json.discard).map((i) => ({ json: i.json }));

// Code node "Build PDFs" (run once for all items).
// Input: every appointment from today on for each due client (from "Get upcoming").
// Output: one item per PDF to upload, with the PracticeQ client to upload to and the PDF as
// binary property `data`. The PDF is written by hand (Helvetica, US Letter) so the workflow
// needs no PDF library on the n8n server.
const s = $('Settings').first().json;
const due = $('Keep due').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.Id);
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();
// In test mode, patients listed in `liveClientIds` (comma-separated) already get real PDFs.
const liveIds = String(s.liveClientIds || '').split(',').map((x) => x.trim()).filter(Boolean);
const isLive = (c) => s.mode === 'live' || liveIds.includes(String(c.clientId));

const fmt = (ms, opts) => new Intl.DateTimeFormat('en-US', { timeZone: s.timezone, ...opts }).format(new Date(ms));
const today = fmt(now, { year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/(\d+)\/(\d+)\/(\d+)/, '$3-$1-$2');

// ---- minimal PDF writer --------------------------------------------------------------
const ASCII = { '‘': "'", '’': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '...' };
const pdfText = (v) => String(v == null ? '' : v)
  .replace(/[‘’“”–—…]/g, (c) => ASCII[c])
  .replace(/[^\x20-\x7E\xA0-\xFF]/g, '?')
  .replace(/[\\()]/g, (c) => '\\' + c);
const clip = (v, n) => { const t = String(v == null ? '' : v); return t.length > n ? t.slice(0, n - 3) + '...' : t; };

function makePdf(pages) {
  // pages: array of content-stream strings. Objects: 1 catalog, 2 pages, 3 Helvetica,
  // 4 Helvetica-Bold, then a page object and a content stream per page.
  const objs = [];
  const kids = pages.map((_, i) => `${5 + i * 2} 0 R`).join(' ');
  objs.push('<< /Type /Catalog /Pages 2 0 R >>');
  objs.push(`<< /Type /Pages /Kids [${kids}] /Count ${pages.length} >>`);
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  pages.forEach((content, i) => {
    objs.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${6 + i * 2} 0 R >>`);
    objs.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
  });
  let out = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
  const offsets = objs.map((o, i) => { const at = out.length; out += `${i + 1} 0 obj\n${o}\nendobj\n`; return at; });
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('');
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, 'latin1'); // every character above is a single byte
}

const text = (x, y, size, str, bold) => `BT /${bold ? 'F2' : 'F1'} ${size} Tf ${x} ${y} Td (${pdfText(str)}) Tj ET\n`;
const rule = (y) => `0.8 G 0.5 w 50 ${y} m 562 ${y} l S\n`;
// Breaks text into lines of at most `width` characters (Helvetica 10pt fits ~95 across the page).
const wrap = (v, width) => String(v || '').trim().split(/\s+/).filter(Boolean).reduce((lines, word) => {
  const last = lines[lines.length - 1];
  if (last !== undefined && (last + ' ' + word).length <= width) lines[lines.length - 1] = last + ' ' + word;
  else lines.push(word);
  return lines;
}, []);
const COLS = [[50, 'Date', 22], [180, 'Time', 40]];

function schedulePdf(c, appts) {
  const pages = [];
  let page = '';
  let y = 0;
  const header = (first) => {
    y = 742;
    if (first) {
      page += text(50, y, 18, 'Upcoming appointments', true); y -= 22;
      page += text(50, y, 11, s.practiceName); y -= 16;
      page += text(50, y, 11, `Patient: ${c.name}`); y -= 16;
      page += text(50, y, 9, `Prepared ${fmt(now, { month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' })}`); y -= 28;
    }
    COLS.forEach(([x, label]) => { page += text(x, y, 10, label, true); });
    y -= 6; page += rule(y); y -= 16;
  };
  header(true);
  for (const a of appts) {
    if (y < 90) { pages.push(page); page = ''; header(false); }
    const time = fmt(a.StartDate, { hour: 'numeric', minute: '2-digit' });
    const cells = [
      fmt(a.StartDate, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }),
      time + (a.Status === 'WaitingConfirmation' ? ' (pending confirmation)' : ''),
    ];
    COLS.forEach(([x, , n], i) => { page += text(x, y, 10, clip(cells[i], n)); });
    y -= 6; page += rule(y); y -= 16;
  }
  y -= 10;
  if (y < 60) { pages.push(page); page = ''; y = 742; }
  page += text(50, y, 10, `${appts.length} upcoming appointment${appts.length === 1 ? '' : 's'}. If anything looks wrong, please call us at ${s.practicePhone}.`);
  const policy = wrap(s.cancellationPolicy, 95);
  if (policy.length) {
    y -= 28;
    if (y - 14 * policy.length < 50) { pages.push(page); page = ''; y = 742; }
    page += text(50, y, 11, 'Cancellation policy', true); y -= 16;
    for (const line of policy) { page += text(50, y, 10, line); y -= 14; }
  }
  pages.push(page);
  return makePdf(pages);
}

// ---- one PDF per due client ----------------------------------------------------------
const out = [];
for (const c of due) {
  // The PracticeQ "client" filter is a partial name/email match, so keep only this client's rows.
  const seen = new Set();
  const appts = rows
    .filter((r) => String(r.ClientId) === String(c.clientId) && OPEN.includes(r.Status) && Number(r.StartDate) > now)
    .filter((r) => !seen.has(r.Id) && seen.add(r.Id))
    .sort((a, b) => a.StartDate - b.StartDate);
  if (!appts.length) continue; // everything was cancelled during the wait

  const live = isLive(c);
  const uploadTo = live ? c.clientId : s.testClientId;
  if (!uploadTo) continue;
  // Earlier summaries for the same patient share the prefix and are replaced after upload.
  const filePrefix = `${live ? '' : `TEST - ${String(c.name).replace(/[\\/:*?"<>|]/g, '')} - `}Upcoming appointments `;
  const fileName = `${filePrefix}${today}.pdf`;
  out.push({
    json: { ...c, uploadTo, count: appts.length, fileName, filePrefix },
    binary: { data: { data: schedulePdf(c, appts).toString('base64'), mimeType: 'application/pdf', fileName, fileExtension: 'pdf' } },
  });
}
return out;

// Code node "Record results" (run once for all items).
// Reads the PracticeQ upload responses, one per "Build PDFs" item in the same order (the
// upload node continues on error, so a failure is an item with an `error` field). Output is a
// log line per PDF, visible in the n8n execution.
const pdfs = $('Build PDFs').all().map((i) => i.json);
const results = $('Upload to client file').all().map((i) => i.json);

return pdfs.map((c, i) => {
  const r = results[i] || { error: 'no response' };
  const base = { clientId: c.clientId, uploadedTo: c.uploadTo, file: c.fileName, appointments: c.count };
  if (!r.error) return { json: { ...base, status: 'uploaded', fileId: r.Id || null } };
  const error = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return { json: { ...base, status: 'failed', attempt: (c.attempts || 0) + 1, error } };
});

// Code node "Pick old summaries" (run once for all items).
// For each PDF that uploaded successfully, keeps the patient's newest summary PDF and picks the
// earlier ones (same name apart from the date) for deletion. PracticeQ's upload reply does not
// include the new file's Id, so "newest" is the matching file with the latest DateCreated in
// the list read right after the upload (or the upload's Id, if PracticeQ ever returns one).
// Nothing is deleted when the upload failed or the file list could not be read, and one
// matching file is always kept, so a patient always has a summary.
const pdfs = $('Build PDFs').all().map((i) => i.json);
const uploads = $('Upload to client file').all().map((i) => i.json);
const lists = $('List client files').all().map((i) => i.json);
const escape = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const out = [];
pdfs.forEach((c, i) => {
  const up = uploads[i] || {};
  const list = lists[i] || {};
  if (up.error || list.error) return;
  let files;
  try {
    files = typeof list.body === 'string' ? JSON.parse(list.body) : list.body;
  } catch (e) {
    return;
  }
  if (!Array.isArray(files)) return;
  const ours = new RegExp(`^${escape(c.filePrefix)}\\d{4}-\\d{2}-\\d{2}\\.pdf$`);
  const matches = files.filter((f) => f && f.Id && ours.test(f.FileName || ''));
  if (matches.length < 2) return;
  const keep = matches.find((f) => up.Id && f.Id === up.Id)
    || matches.reduce((a, b) => (Number(b.DateCreated) > Number(a.DateCreated) ? b : a));
  for (const f of matches) {
    if (f.Id !== keep.Id) out.push({ json: { clientId: c.uploadTo, fileId: f.Id, fileName: f.FileName } });
  }
});
return out;

// Code node "Retries" (run once for all items).
// Puts each failed upload back in the queue so it is tried again about 10 minutes later
// (3 attempts in total). The row is dated so that it falls due 10 minutes from now.
const s = $('Settings').first().json;
const MAX_ATTEMPTS = 3;
const bufferMs = Number(s.bufferMinutes) * 60000;
const pdfs = $('Build PDFs').all().map((i) => i.json);
const results = $('Upload to client file').all().map((i) => i.json);

return pdfs.flatMap((c, i) => {
  const r = results[i] || { error: 'no response' };
  const attempts = (c.attempts || 0) + 1;
  if (!r.error || attempts >= MAX_ATTEMPTS) return [];
  return [{
    json: {
      clientId: String(c.clientId), clientName: c.name || '', clientEmail: c.email || '',
      eventAt: Date.now() - bufferMs + 10 * 60000, isBooking: true, attempts,
    },
  }];
});
